  text: lines.join('\n'), result, snapshot, incomplete, suite: run.suite, wait: run.wait,
  graderErrors: ungraded.map((r) => `${r.id}: ${r.graderError}`),
} }];

// Slack refused the scorecard after its retries. The run is not saved as the comparison baseline,
// and it ends as failed after the webhook gets its answer.
const error = $input.first().json.error || {};
return [{ json: { slackError: (String(error.message || 'unknown error') + (error.description ? `: ${error.description}` : '')).slice(0, 300) } }];

// Saves this run as the baseline for the next comparison, but only when it is complete (every case graded)
// and its scorecard reached Slack (or Slack is not set up). Otherwise the next run still compares against
// the last run someone actually saw.
const card = $('Build Scorecard').first().json;
const slackFailed = $('Note Slack Failure').isExecuted;
const slackSet = $('Load Cases').first().json.run.slackSet;
const store = $getWorkflowStaticData('global');
let saved = false;
if (!card.incomplete && !slackFailed) {
  store.runs = store.runs || {};
  store.history = store.history || {};
  store.runs[card.suite] = card.snapshot;
  const list = store.history[card.suite] || [];
  list.push({ runId: card.snapshot.runId, at: card.snapshot.at, verdict: card.snapshot.verdict, passRate: card.snapshot.passRate });
  store.history[card.suite] = list.slice(-10);
  saved = true;
}
const problems = [];
if (card.incomplete) problems.push(`${card.graderErrors.length} case(s) could not be graded (${card.graderErrors.join('; ').slice(0, 600)})`);
if (slackFailed) problems.push(`the scorecard could not be posted to Slack (${$('Note Slack Failure').first().json.slackError})`);
const result = { ...card.result, savedAsBaseline: saved, slackPosted: slackSet && !slackFailed };
return [{ json: {
  ok: problems.length === 0,
  result,
  failure: problems.length
    ? `QA run ${result.runId} for ${result.suite} did not finish: ${problems.join('; ')}. Verdict so far: ${result.verdict}, ${result.passed} of ${result.total} passed. It was not saved as the baseline for the next comparison.`
    : null,
} }];
